// ============================================================================
// SELFTEST KERNEL: feeds the known target base directly through the full
// monolithic pipeline (enumeration -> wide PBKDF2 -> BIP32 -> EC -> hash160)
// on real silicon. Expected: FOUND with the documented private key.
// ============================================================================
__global__ void __launch_bounds__(256) kernel_scanner_wide(
    uint64_t start_k,
    uint32_t bases_per_thread,
    uint32_t* found_count,
    uint8_t* found_privkeys,
    uint16_t* found_indices
) {
    uint64_t tid = blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t stride = (uint64_t)gridDim.x * blockDim.x;

    for (uint32_t b = 0; b < bases_per_thread; b++) {
        uint64_t k = start_k + b * stride + tid;
        uint16_t phrase[12];
        generate_phrase12(k, phrase);
        process_base_vocabulary_wide(phrase, found_count, found_privkeys, found_indices);
    }
}

__global__ void kernel_selftest(
    uint32_t* found_count,
    uint8_t* found_privkeys,
    uint16_t* found_indices
) {
    if (threadIdx.x == 0 && blockIdx.x == 0) {
        uint16_t base[11] = {759, 1078, 213, 623, 521, 319, 416, 302, 566, 1104, 191};
        process_base_vocabulary_wide(base, found_count, found_privkeys, found_indices);

        /* stage-by-stage diagnostics for candidate 1666 */
        printf("\n[DIAG] device repr[1666] = %016llx\n",
               (unsigned long long)WLBP_LOAD(&d_repr_table[1666]));
        printf("[DIAG] device Gwin_x[0].d[0] = %08x (expect 16f81798)\n",
               (unsigned)d_Gwin_x[0].d[0]);

        uint64_t prefix_w[16], cur;
        uint32_t bits = 0, prefix_len = 0;
        int wi = 0;
        wlbp_base_prefix_build(d_repr_table, base, prefix_w, &cur, &bits, &wi, &prefix_len);
        printf("[DIAG] prefix_len = %u\n", prefix_len);

        uint64_t wb = WLBP_LOAD(&d_repr_table[1666]);
        uint64_t key_w[16];
        wlbp_keyblock_tail_swap(prefix_w, cur, bits, wi, wb, (uint32_t)wlbp_wb_len(wb), key_w);
        printf("[DIAG] key_w[0] = %016llx\n", (unsigned long long)key_w[0]);

        uint8_t seed[64];
        pbkdf2_sha512_keyblock_fast(key_w, prefix_len + (uint32_t)wlbp_wb_len(wb), PBKDF2_ITERATIONS, seed);
        printf("[DIAG] seed[0..7] = ");
        for (int i = 0; i < 8; i++) printf("%02x", seed[i]);
        printf(" (expect 4cd832a5c862ef51)\n");

        uint8_t I[64];
        master_hmac_fast(seed, I);
        printf("[DIAG] master[0..7] = ");
        for (int i = 0; i < 8; i++) printf("%02x", I[i]);
        printf(" (expect 7441876923f2e91c)\n");

        /* BIP32 chain on device */
        uint8_t master_key[32], master_chaincode[32];
        memcpy(master_key, I, 32);
        memcpy(master_chaincode, I + 32, 32);
        uint8_t key[32], chaincode[32], temp_key[32], temp_chaincode[32];
        derive_child_key(master_key, master_chaincode, 44, key, chaincode, true, false);
        derive_child_key(key, chaincode, 0, temp_key, temp_chaincode, true, false);
        memcpy(key, temp_key, 32); memcpy(chaincode, temp_chaincode, 32);
        derive_child_key(key, chaincode, 0, temp_key, temp_chaincode, true, false);
        memcpy(key, temp_key, 32); memcpy(chaincode, temp_chaincode, 32);
        derive_child_key(key, chaincode, 0, temp_key, temp_chaincode, false, false);
        memcpy(key, temp_key, 32); memcpy(chaincode, temp_chaincode, 32);
        uint8_t private_key[32];
        derive_child_key(key, chaincode, 0, private_key, temp_chaincode, false, false);
        printf("[DIAG] privkey[0..7] = ");
        for (int i = 0; i < 8; i++) printf("%02x", private_key[i]);
        printf(" (expect 20bbcda671e9f66c)\n");

        uint8_t pubkey[33];
        secp256k1_get_pubkey_compressed(private_key, pubkey);
        printf("[DIAG] pubkey[0..7] = ");
        for (int i = 0; i < 8; i++) printf("%02x", pubkey[i]);
        printf(" (expect 026397423d347ccb)\n");

        uint8_t sha_hash[32], h160[20];
        sha256(pubkey, 33, sha_hash);
        ripemd160(sha_hash, 32, h160);
        printf("[DIAG] hash160[0..7] = ");
        for (int i = 0; i < 8; i++) printf("%02x", h160[i]);
        printf(" (expect 232fb8a4bb0b8be8)\n");

        printf("[DIAG] d_num_targets = %u\n", d_num_targets);
        if (d_num_targets > 0) {
            printf("[DIAG] target[0] = ");
            for (int i = 0; i < 8; i++) printf("%02x", d_target_hashes_ptr[i]);
            printf("...\n");
        }
    }
}

// ============================================================================
// Host functions
// ============================================================================

void load_wordlist(const char* filename, char wordlist[2048][16]) {
    FILE* f = fopen(filename, "r");
    if (!f) {
        printf("Error: Cannot open wordlist %s\n", filename);
        exit(1);
    }
    
    char line[64];
    int idx = 0;
    while (fgets(line, sizeof(line), f) && idx < 2048) {
        line[strcspn(line, "\r\n")] = 0;
        // Initialize buffer to zeros to avoid garbage
        memset(wordlist[idx], 0, 16);
        // Copy full word (up to 15 chars to leave room for null terminator)
        strncpy(wordlist[idx], line, 15);
        idx++;
    }
    fclose(f);
    printf("First word in list: '%s'\n", wordlist[0]);
    printf("Last word (idx-1): '%s'\n", wordlist[idx-1]);
    printf("Loaded %d words from wordlist\n", idx);
}

void load_target_words(const char* filename, char wordlist[2048][16], uint16_t* indices, uint32_t* count) {
    FILE* f = fopen(filename, "r");
    if (!f) {
        printf("Error: Cannot open words file %s\n", filename);
        exit(1);
    }
    
    char word[64];
    *count = 0;
    while (fscanf(f, "%s", word) == 1 && *count < MAX_WORDS) {
        bool found_match = false;
        // Find word in wordlist
        for (int i = 0; i < 2048; i++) {
            if (strcmp(word, wordlist[i]) == 0) {
                indices[*count] = i;
                (*count)++;
                found_match = true;
                break;
            }
        }
        if (!found_match) {
             printf("Warning: Word '%s' not found in wordlist!\n", word);
        }
    }
    fclose(f);
    printf("Loaded %u target words\n", *count);
}

uint64_t factorial(int n) {
    uint64_t f = 1;
    for (int i = 2; i <= n; i++) f *= i;
    return f;
}

// ============================================================================
// Main
// ============================================================================
int main(int argc, char** argv) {
    printf("============================================================\n");
    printf("  BIP39 CUDA Scanner v6.0 - ULTRA SPEED MODE\n");
    printf("============================================================\n");
    
    if (argc < 3) {
        printf("Usage: %s -words <words.txt> -a <addresses.txt> [--bloom <MB>]\n", argv[0]);
        return 1;
    }

    // Increase stack size to prevent corruption in deep crypto functions
    // E8 wide default: 49152 (128 chains x 128B state + crypto); x2/x3 need less
    cudaDeviceSetLimit(cudaLimitStackSize, 49152);
    cudaDeviceSetLimit(cudaLimitPrintfFifoSize, 1024 * 1024 * 32); // 32MB printf buffer
    
    const char* words_file = NULL;
    const char* addr_file = NULL;
    uint64_t batch_size = BATCH_SIZE_DEFAULT;
    int k2_blocks = 512; /* E13: 512 x 128-thread blocks = 65,536 threads (3 blocks/SM at ~158 regs) */
    int selftest = 0;
    int depth = 1; /* 1 = solo (minimum regs, max occupancy), 2 = x2, 3 = x3, 0 = wide */

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-words") == 0 && i + 1 < argc) words_file = argv[++i];
        else if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) addr_file = argv[++i];
        else if (strcmp(argv[i], "--batch") == 0 && i + 1 < argc) batch_size = atoll(argv[++i]);
        else if (strcmp(argv[i], "--k2blocks") == 0 && i + 1 < argc) k2_blocks = atoi(argv[++i]);
        else if (strcmp(argv[i], "--selftest") == 0) selftest = 1;
        else if (strcmp(argv[i], "--depth") == 0 && i + 1 < argc) depth = atoi(argv[++i]);
    }

    if (!words_file || !addr_file) {
        printf("Usage: %s -words <words.txt> -a <addresses.txt> [--bloom <MB>] [--batch <candidates>]\n", argv[0]);
        return 1;
    }
    if (batch_size < 65536) batch_size = 65536;

    // Load addresses
    std::vector<uint8_t> target_hashes;
    int num_targets = 0;
    
    FILE* f_addr = fopen(addr_file, "r");
    if (f_addr) {
        char line[128];
        while (fgets(line, sizeof(line), f_addr)) {
            line[strcspn(line, "\r\n")] = 0;
            if (strlen(line) < 20) continue;
            
            uint8_t hash[20];
            if (base58_decode_address(line, hash)) {
                for(int i=0; i<20; i++) target_hashes.push_back(hash[i]);
            }
        }
        fclose(f_addr);
        num_targets = target_hashes.size() / 20;
        printf("Loaded %d target addresses\n", num_targets);
    } else {
        printf("Error: Cannot open address file %s\n", addr_file);
        return 1;
    }
    
    // Load wordlist
    char wordlist[2048][16];
    load_wordlist("wordlist.txt", wordlist);
    
    // Load target words
    uint16_t h_word_indices[MAX_WORDS];
    uint32_t word_count;
    load_target_words(words_file, wordlist, h_word_indices, &word_count);
    
    printf("Word count: %u\n", word_count);
    printf("Words: ");
    for (uint32_t i = 0; i < word_count; i++) {
        printf("%s ", wordlist[h_word_indices[i]]);
    }
    printf("\n");

    // P2: precompute required words + candidate pool (fixed per launch).
    // Required positions in the words file: 0, 7, 10, 12 (galaxy, egg, venture, oxygen).
    if (word_count < 13) {
        printf("Error: required-words mode needs at least 13 words (got %u)\n", word_count);
        return 1;
    }
    {
        const uint32_t required_positions[4] = {0, 7, 10, 12};
        uint16_t h_req[4];
        uint16_t h_avail[MAX_WORDS];
        uint32_t avail_count = 0;
        for (uint32_t r = 0; r < 4; r++) h_req[r] = h_word_indices[required_positions[r]];
        for (uint32_t i = 0; i < word_count; i++) {
            bool is_req = false;
            for (int r = 0; r < 4; r++) if (i == required_positions[r]) { is_req = true; break; }
            if (!is_req) h_avail[avail_count++] = h_word_indices[i];
        }
        cudaMemcpyToSymbol(d_req_words, h_req, sizeof(h_req));
        cudaMemcpyToSymbol(d_avail_words, h_avail, avail_count * sizeof(uint16_t));
        cudaMemcpyToSymbol(d_avail_count, &avail_count, sizeof(uint32_t));
        printf("P2 pool: %u required + %u available\n", 4u, avail_count);
    }
    
    // Calculate total permutations
    uint64_t total_perms = factorial(word_count);
    printf("Total permutations: %llu\n", (unsigned long long)total_perms);
    
    // Prepare factorials
    uint64_t h_factorials[25];
    h_factorials[0] = 1;
    for (int i = 1; i <= 24; i++) h_factorials[i] = h_factorials[i-1] * i;
    
    // Copy to device
    cudaMemcpyToSymbol(d_word_indices, h_word_indices, MAX_WORDS * sizeof(uint16_t));
    cudaMemcpyToSymbol(d_word_count, &word_count, sizeof(uint32_t));
    cudaMemcpyToSymbol(d_factorials, h_factorials, 25 * sizeof(uint64_t));
    
    // Allocate device memory
    
    // E6: no intermediate buffers - the monolithic thread generates, filters,
    // enumerates and derives everything in-thread. Only result storage remains.


    // WLBP-PR ETAPA B/C: host builds the 2048-representative table (16KB) once;
    // folded round constants are compile-time initialized (__constant__).
    wlbp_upload_repr_table();

    // P5: build + upload the fixed-base windowed G table (60KB, built once).
    secp256k1_gwin_upload();

    // E6 geometry: batch_size = TOTAL bases per launch, split across
    // k2_blocks x 256 threads (grid-stride) -> bases_per_thread each.
    uint64_t threads_total = (uint64_t)k2_blocks * 256;
    uint32_t bases_per_thread = (uint32_t)(batch_size / threads_total);
    if (bases_per_thread < 1) bases_per_thread = 1;
    uint64_t bases_per_launch = threads_total * (uint64_t)bases_per_thread;

    // Found results storage
    uint32_t* d_found_count;
    cudaMalloc(&d_found_count, sizeof(uint32_t));
    cudaMemset(d_found_count, 0, sizeof(uint32_t));

    uint8_t* d_found_privkeys;
    cudaMalloc(&d_found_privkeys, 100 * 32); // Store up to 100 found keys

    uint16_t* d_found_indices;
    cudaMalloc(&d_found_indices, 100 * MAX_WORDS * sizeof(uint16_t));
    
    // Target hashes pointers
    uint32_t use_bloom = 0;
    cudaMemcpyToSymbol(d_use_bloom, &use_bloom, sizeof(uint32_t));
    
    if (num_targets > 0) {
        uint8_t* d_targets;
        cudaMalloc(&d_targets, target_hashes.size());
        cudaMemcpy(d_targets, target_hashes.data(), target_hashes.size(), cudaMemcpyHostToDevice);
        
        // Update device symbols
        cudaMemcpyToSymbol(d_target_hashes_ptr, &d_targets, sizeof(uint8_t*));
        cudaMemcpyToSymbol(d_num_targets, &num_targets, sizeof(uint32_t));
    }
    
    printf("\n============================================================\n");
    printf("E6 MONOLITHIC SCANNER - one thread does the whole process\n");
    printf("Required words: 4 fixed + pool, position-12 enumerated over ALL 2048\n");
    printf("Geometry: %d blocks x 128 threads x %u bases/thread = %llu bases/launch\n",
           k2_blocks, bases_per_thread, (unsigned long long)bases_per_launch);
    printf("Per thread: %u bases x 2048 candidates = %u words processed, ~%u derivations\n",
           bases_per_thread, bases_per_thread * 2048, bases_per_thread * 128);
    printf("Press Ctrl+C to stop\n");
    printf("============================================================\n\n");

    clock_t start_time = clock();

    // E-SELFTEST: known target base through the full monolithic pipeline
    if (selftest) {
        printf("\n[SELFTEST] target base -> full monolithic pipeline on silicon...\n");
        cudaMemset(d_found_count, 0, sizeof(uint32_t));
        kernel_selftest<<<1, 32>>>(d_found_count, d_found_privkeys, d_found_indices);
        cudaError_t err = cudaDeviceSynchronize();
        if (err != cudaSuccess) { printf("[SELFTEST] CUDA error: %s\n", cudaGetErrorString(err)); return 1; }
        uint32_t found_now;
        cudaMemcpy(&found_now, d_found_count, sizeof(uint32_t), cudaMemcpyDeviceToHost);
        if (found_now > 0) {
            uint8_t h_priv[100 * 32];
            uint16_t h_idx[100 * 12];
            cudaMemcpy(h_priv, d_found_privkeys, found_now * 32, cudaMemcpyDeviceToHost);
            cudaMemcpy(h_idx, d_found_indices, found_now * 12 * sizeof(uint16_t), cudaMemcpyDeviceToHost);
            const uint8_t expected_priv[32] = {
                0x20,0xbb,0xcd,0xa6,0x71,0xe9,0xf6,0x6c,0xfe,0xde,0xdb,0x3c,0xc6,0x76,0x35,0x84,
                0xc0,0x2d,0xb5,0x53,0x0c,0xb1,0x97,0x5d,0xfa,0x82,0xd0,0x03,0xe5,0x23,0x3f,0xaf
            };
            for (uint32_t f = 0; f < found_now && f < 100; f++) {
                printf("[SELFTEST] FOUND #%u\n  privkey: ", f);
                for (int i = 0; i < 32; i++) printf("%02x", h_priv[f * 32 + i]);
                printf("\n  indices: ");
                for (int w = 0; w < 12; w++) printf("%u ", h_idx[f * 12 + w]);
                printf("\n");
                int ok = memcmp(h_priv + f * 32, expected_priv, 32) == 0;
                printf("[SELFTEST] privkey vs documented: %s\n", ok ? "MATCH" : "MISMATCH");
                if (!ok) { printf("[SELFTEST] RESULT: FAIL\n"); return 1; }
            }
            printf("[SELFTEST] RESULT: PASS - full pipeline verified on silicon\n");
        } else {
            printf("[SELFTEST] RESULT: FAIL - no match found\n");
            return 1;
        }
        return 0;
    }

    // E6: single-kernel loop - the monolithic scanner does everything
    uint64_t k = 0;
    while (true) {
        cudaMemset(d_found_count, 0, sizeof(uint32_t));

        if (depth == 1)
            kernel_scanner_solo<<<k2_blocks, 128>>>(
                k, bases_per_thread,
                d_found_count, d_found_privkeys, d_found_indices
            );
        else if (depth == 0)
            kernel_scanner_wide<<<k2_blocks, 256>>>(
                k, bases_per_thread,
                d_found_count, d_found_privkeys, d_found_indices
            );
        else if (depth == 3)
            kernel_scanner_x3<<<k2_blocks, 128>>>(
                k, bases_per_thread,
                d_found_count, d_found_privkeys, d_found_indices
            );
        else
            kernel_scanner_x2<<<k2_blocks, 128>>>(
                k, bases_per_thread,
                d_found_count, d_found_privkeys, d_found_indices
            );
        cudaDeviceSynchronize();

        // Check found
        uint32_t found_now;
        cudaMemcpy(&found_now, d_found_count, sizeof(uint32_t), cudaMemcpyDeviceToHost);
        if (found_now > 0) {
            g_found.store(found_now);
            printf("\n[+] FOUND %u MATCHES!\n", found_now);
            break;
        }

        g_permutations_tested += bases_per_launch * 2048;   // candidates checked (comparable to old metric)
        g_valid_checksums += bases_per_launch * 128;        // full derivations completed

        k += bases_per_launch;

        // Display progress every ~10 launches
        if ((k / bases_per_launch) >= 1) {
            double elapsed = (double)(clock() - start_time) / CLOCKS_PER_SEC;
            double rate = g_permutations_tested / elapsed;
            printf("\n[E6 SCANNER] Bases: %llu | Derivations: %llu | Bases/s: %.2f M | Elapsed: %.1fs\n",
                   (unsigned long long)g_permutations_tested.load(),
                   (unsigned long long)g_valid_checksums.load(),
                   rate / 1000000.0,
                   elapsed);
            fflush(stdout);
        }
    }
    
    printf("\n\n============================================================\n");
    printf("SCAN COMPLETE\n");
    printf("Total permutations: %llu\n", (unsigned long long)g_permutations_tested.load());
    printf("Valid checksums: %llu\n", (unsigned long long)g_valid_checksums.load());
    printf("Found: %u\n", g_found.load());
    printf("============================================================\n");
    
    
    // Cleanup
    cudaFree(d_found_count);
    cudaFree(d_found_privkeys);
    cudaFree(d_found_indices);
    
    return 0;
}
